def east_asian_width(character):
    if not isinstance(character, str) or len(character) != 1:
        raise TypeError('east_asian_width() argument must be a unicode character, not ' + type(character).__name__)
    point = ord(character)
    low, high = 0, len(_east_asian_boundaries)
    while low + 1 < high:
        middle = (low + high) // 2
        if _east_asian_boundaries[middle][0] <= point:
            low = middle
        else:
            high = middle
    return _east_asian_boundaries[low][1]
